#include <stdio.h>

int main() {
    long long a, b, c;
    if (scanf("%lld %lld %lld", &a, &b, &c) == 3) {
        if (a + b > c && a + c > b && b + c > a) printf("Valid\n");
        else printf("Not Valid\n");
    }
    return 0;
}

